// SetCursor sends the zwp_tablet_tool_v2.set_cursor request: set the tablet tool's surface.
//
// Sets the surface of the cursor used for this tool on the given
// tablet. This request only takes effect if the tool is in proximity
// of one of the requesting client's surfaces or the surface parameter
// is the current pointer surface. If there was a previous surface set
// with this request it is replaced. If surface is NULL, the cursor
// image is hidden.
//
// The parameters hotspot_x and hotspot_y define the position of the
// pointer surface relative to the pointer location. Its top-left corner
// is always at (x, y) - (hotspot_x, hotspot_y), where (x, y) are the
// coordinates of the pointer location, in surface-local coordinates.
//
// On surface.attach requests to the pointer surface, hotspot_x and
// hotspot_y are decremented by the x and y parameters passed to the
// request. Attach must be confirmed by wl_surface.commit as usual.
//
// The hotspot can also be updated by passing the currently set pointer
// surface to this request with new values for hotspot_x and hotspot_y.
//
// The current and pending input regions of the wl_surface are cleared,
// and wl_surface.set_input_region is ignored until the wl_surface is no
// longer used as the cursor. When the use as a cursor ends, the current
// and pending input regions become undefined, and the wl_surface is
// unmapped.
//
// This request gives the surface the role of a zwp_tablet_tool_v2 cursor. A
// surface may only ever be used as the cursor surface for one
// zwp_tablet_tool_v2. If the surface already has another role or has
// previously been used as cursor surface for a different tool, a
// protocol error is raised.
func (self *ZwpTabletToolV2) SetCursor(serial uint32, surface *WlSurface, hotspotX int32, hotspotY int32) {
	msg := self.Begin(0)
	msg.Uint(serial)
	var surfaceID uint32
	if surface != nil {
		surfaceID = surface.ID()
	}
	msg.Object(surfaceID)
	msg.Int(hotspotX)
	msg.Int(hotspotY)
	msg.Done()
}

// Destroy sends the zwp_tablet_tool_v2.destroy request: destroy the tool object.
//
// This destroys the client's resource for this tool object.
//
// This is a destructor: the proxy must not be used afterwards.
func (self *ZwpTabletToolV2) Destroy() {
	msg := self.Begin(1)
	msg.Done()
	self.MarkDestroyed()
}

// ZwpTabletV2 is the client proxy of the zwp_tablet_v2 interface: graphics tablet device.
//
// The zwp_tablet_v2 interface represents one graphics tablet device. The
// tablet interface itself does not generate events; all events are
// generated by zwp_tablet_tool_v2 objects when in proximity above a tablet.
//
// A tablet has a number of static characteristics, e.g. device name and
// pid/vid. These capabilities are sent in an event sequence after the
// zwp_tablet_seat_v2.tablet_added event. This initial event sequence is
// terminated by a zwp_tablet_v2.done event.
//
// Highest version known to these bindings: 2.
type ZwpTabletV2 struct {
	wire.Proxy
	onName    func(ZwpTabletV2NameEvent)
	onId      func(ZwpTabletV2IdEvent)
	onPath    func(ZwpTabletV2PathEvent)
	onDone    func(ZwpTabletV2DoneEvent)
	onRemoved func(ZwpTabletV2RemovedEvent)
	onBustype func(ZwpTabletV2BustypeEvent)
}

